static const size_t NUM_EMBEDDED_ASSETS = sizeof(EMBEDDED_ASSETS) / sizeof(EMBEDDED_ASSETS[0]);

const embedded_asset_t* find_embedded_ui_asset(const std::string& name) {
    if (name.empty()) return nullptr;

    // Normalize path: extract filename
    std::string base = name;
    for (char& c : base) {
        if (c == '\\') c = '/';
    }
    size_t slash = base.rfind('/');
    if (slash != std::string::npos) {
        base = base.substr(slash + 1);
    }

    // Convert lookup name to lower-case
    std::string lower_base = base;
    for (char& c : lower_base) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }

    for (size_t i = 0; i < NUM_EMBEDDED_ASSETS; ++i) {
        const auto& a = EMBEDDED_ASSETS[i];
        std::string lower_name = a.name;
        for (char& c : lower_name) {
            c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        }
        if (lower_base == lower_name) {
            return &a;
        }
        if (lower_base + ".bmp" == lower_name) {
            return &a;
        }
    }
    return nullptr;
}

